INSERT INTO "public"."brain_map_collocations" VALUES ('bbdcd586-ec40-4989-85f9-03667df8bd45', 'b7cc3605-7b42-4fcd-9829-9514451f9ac3', 'maintain a relationship', '관계를 유지하다', 'They maintained a close relationship for twenty years.', 1, 0);
INSERT INTO "public"."brain_map_collocations" VALUES ('263eb771-6b3f-4c6b-9a0b-ce038e32c367', 'b7cc3605-7b42-4fcd-9829-9514451f9ac3', 'maintain quality', '품질을 유지하다', 'Small farms find it hard to maintain quality at scale.', 1, 1);
INSERT INTO "public"."brain_map_collocations" VALUES ('cd585d1f-9063-43ef-a77c-bb1832f339b0', 'b7cc3605-7b42-4fcd-9829-9514451f9ac3', 'maintain order', '질서를 유지하다', 'The teachers struggled to maintain order in the hall.', 2, 2);
INSERT INTO "public"."brain_map_collocations" VALUES ('51fe79e8-6dfc-4ecf-b156-7071ba9a1d8e', 'b7cc3605-7b42-4fcd-9829-9514451f9ac3', 'maintain control', '통제력을 유지하다', 'She maintained control of the car on the icy road.', 2, 3);
INSERT INTO "public"."brain_map_collocations" VALUES ('231cc285-eb3e-49fc-a334-bb0909b9cb8f', '24280243-dbbd-4a21-8e23-93b8d5fb4252', 'directly affect', '직접적으로 영향을 미치다', 'The new rule directly affects part-time workers.', 1, 0);
INSERT INTO "public"."brain_map_collocations" VALUES ('12420fff-e52a-4f7a-8d82-3c8868cc2a92', '24280243-dbbd-4a21-8e23-93b8d5fb4252', 'adversely affect', '악영향을 미치다', 'Lack of sleep adversely affects concentration.', 2, 1);
INSERT INTO "public"."brain_map_collocations" VALUES ('a6357808-63c7-4468-93a3-09c7fb90adc9', '24280243-dbbd-4a21-8e23-93b8d5fb4252', 'be deeply affected by', '~에 깊이 영향을 받다', 'The whole town was deeply affected by the flood.', 2, 2);
INSERT INTO "public"."brain_map_collocations" VALUES ('489665a0-90ff-45bb-aa65-cc86a45e6288', '5d2a22dc-a9ed-4bf9-896b-1bf530d035cf', 'raise an issue', '문제를 제기하다', 'She raised the issue at the staff meeting.', 1, 0);
INSERT INTO "public"."brain_map_collocations" VALUES ('7ee51288-542b-40c4-94c8-c1c48ad84709', '5d2a22dc-a9ed-4bf9-896b-1bf530d035cf', 'address an issue', '문제를 다루다', 'The report fails to address the real issue.', 1, 1);
INSERT INTO "public"."brain_map_collocations" VALUES ('069228a9-0755-4101-8ade-7c82eabbd969', '5d2a22dc-a9ed-4bf9-896b-1bf530d035cf', 'a controversial issue', '논란이 되는 쟁점', 'Voting age is a controversial issue in many countries.', 2, 2);

--
-- Data for Name: brain_map_meanings; Type: TABLE DATA; Schema: public; Owner: -
--

INSERT INTO "public"."brain_map_meanings" VALUES ('5fb5b2f6-7607-41c4-acf6-700e4f710f78', 'b7cc3605-7b42-4fcd-9829-9514451f9ac3', '(상태를) 유지하다', 'to keep something at the same level or in the same condition', '핵심 의미가 가장 직접적으로 드러나는 용법. 가만히 두는 것이 아니라 노력해서 계속 이어가는 것이 포인트다.', 'maintain good health', 0);
INSERT INTO "public"."brain_map_meanings" VALUES ('454de04a-1f0e-4470-b33e-a0a68e5530c1', 'b7cc3605-7b42-4fcd-9829-9514451f9ac3', '(기계·건물을) 정비하다, 관리하다', 'to keep equipment in good condition by checking and repairing it', '상태를 계속 이어지게 하려면 손봐야 한다. "유지하다"에 실제 작업이 붙은 용법.', 'maintain a machine', 1);
INSERT INTO "public"."brain_map_meanings" VALUES ('204dea47-54fa-4642-9eca-4eba5cc5cde6', 'b7cc3605-7b42-4fcd-9829-9514451f9ac3', '(의견을) 계속 주장하다', 'to keep saying that something is true, even when others disagree', '유지되는 대상이 상태가 아니라 "내 입장"인 경우. 반대에도 입장을 끊지 않고 이어간다는 점에서 핵심 의미와 연결된다.', 'maintain his innocence', 2);
INSERT INTO "public"."brain_map_meanings" VALUES ('de7a119c-936f-4151-8813-8aaa4afe5b0b', '24280243-dbbd-4a21-8e23-93b8d5fb4252', '~에 영향을 미치다', 'to cause a change in something', '가장 기본적인 용법. 목적어를 바로 취하는 타동사라서 "affect to"처럼 쓰지 않는다.', 'affect the results', 0);
INSERT INTO "public"."brain_map_meanings" VALUES ('edfd5f8d-7608-412c-9cc1-aab9d4f5ba31', '24280243-dbbd-4a21-8e23-93b8d5fb4252', '(감정적으로) 마음을 움직이다', 'to cause a strong emotion in someone', '"바꾸다"의 대상이 사람의 마음인 경우. 보통 수동태 be deeply affected 형태로 자주 쓰인다.', 'deeply affected by the news', 1);
INSERT INTO "public"."brain_map_meanings" VALUES ('3f2ed776-322e-468d-b9cc-8ebccfc6ec5b', '5d2a22dc-a9ed-4bf9-896b-1bf530d035cf', '(다뤄야 할) 문제, 쟁점', 'an important topic that people are discussing or arguing about', '드러나서 다 같이 다뤄야 하는 상태가 된 것. problem과 달리 "해결해야 할 골칫거리"보다 "논의 대상"에 가깝다.', 'an important issue', 0);
INSERT INTO "public"."brain_map_meanings" VALUES ('8e21c42d-eb36-4abc-aa16-eff0fc6e1185', '5d2a22dc-a9ed-4bf9-896b-1bf530d035cf', '(정기 간행물의) 호', 'one of a regular series of a magazine or newspaper', '"밖으로 내보낸 것"이라는 감각. 이번 달에 세상에 나온 한 권이 this month’s issue다.', 'this month''s issue', 1);
INSERT INTO "public"."brain_map_meanings" VALUES ('e6965db0-3db8-4b4d-a65b-867eb8136c0e', '5d2a22dc-a9ed-4bf9-896b-1bf530d035cf', '(공식적으로) 발급하다, 발표하다', 'to officially give out or announce something', '동사로 쓰일 때의 용법. 기관이 무언가를 밖으로 내보낸다는 점에서 명사 뜻과 뿌리가 같다.', 'issue a statement', 2);

