INSERT INTO "public"."brain_map_sentences" VALUES ('595e5150-28fd-4701-a086-3016bfd02694', 'b7cc3605-7b42-4fcd-9829-9514451f9ac3', 'Regular exercise helps maintain good health.', '규칙적인 운동은 건강을 유지하는 데 도움이 된다.', '상태를 유지하다', 'maintain good health', 1, 0);
INSERT INTO "public"."brain_map_sentences" VALUES ('4457f641-778c-4151-a762-b6d33e19f650', 'b7cc3605-7b42-4fcd-9829-9514451f9ac3', 'It is difficult to maintain a long-distance relationship.', '장거리 연애를 유지하는 것은 어렵다.', '관계를 이어가다', 'maintain a long-distance relationship', 2, 1);
INSERT INTO "public"."brain_map_sentences" VALUES ('b82b5ae4-3d1f-4fa0-abea-6fa887c66455', 'b7cc3605-7b42-4fcd-9829-9514451f9ac3', 'The machine must be properly maintained to work safely.', '그 기계는 안전하게 작동하려면 제대로 정비되어야 한다.', '기계를 정비하다', 'properly maintained', 3, 2);
INSERT INTO "public"."brain_map_sentences" VALUES ('fcd12a4d-2bff-49ce-a719-eddc3d564c64', 'b7cc3605-7b42-4fcd-9829-9514451f9ac3', 'He maintained that he had never seen the document.', '그는 그 문서를 결코 본 적이 없다고 주장했다.', '의견을 주장하다', 'maintained that', 4, 3);
INSERT INTO "public"."brain_map_sentences" VALUES ('93a6594a-cb26-4199-8798-31c7502e4bd8', 'b7cc3605-7b42-4fcd-9829-9514451f9ac3', 'The company struggled to maintain quality as it grew.', '그 회사는 성장하면서 품질을 유지하는 데 어려움을 겪었다.', '수준을 유지하다', 'maintain quality', 3, 4);
INSERT INTO "public"."brain_map_sentences" VALUES ('13765e9f-2189-4a02-a77d-70081eaf29d2', '24280243-dbbd-4a21-8e23-93b8d5fb4252', 'The weather can affect how well you sleep.', '날씨는 당신이 얼마나 잘 자는지에 영향을 줄 수 있다.', '영향을 미치다', 'affect how well you sleep', 1, 0);
INSERT INTO "public"."brain_map_sentences" VALUES ('aa0226f8-802b-458f-b1d2-7aab7eae4cad', '24280243-dbbd-4a21-8e23-93b8d5fb4252', 'Rising prices affect low-income families the most.', '물가 상승은 저소득 가정에 가장 큰 영향을 미친다.', '집단에 영향을 미치다', 'affect low-income families', 2, 1);
INSERT INTO "public"."brain_map_sentences" VALUES ('49db5e2b-6a8e-42d5-b302-514b2c55989c', '24280243-dbbd-4a21-8e23-93b8d5fb4252', 'She was deeply affected by her grandfather’s death.', '그녀는 할아버지의 죽음에 깊이 마음이 흔들렸다.', '감정을 움직이다', 'deeply affected', 3, 2);
INSERT INTO "public"."brain_map_sentences" VALUES ('a52d57f0-d321-43c4-ba7c-aa203c0f7bce', '5d2a22dc-a9ed-4bf9-896b-1bf530d035cf', 'Climate change is the most urgent issue of our time.', '기후 변화는 우리 시대의 가장 시급한 문제다.', '사회적 쟁점', 'the most urgent issue', 2, 0);
INSERT INTO "public"."brain_map_sentences" VALUES ('b7dd2201-34e0-4bfa-9a9a-09c6f7d33c9d', '5d2a22dc-a9ed-4bf9-896b-1bf530d035cf', 'I have an issue with the way this was decided.', '나는 이것이 결정된 방식에 이견이 있다.', '개인적인 이견·불만', 'an issue with', 3, 1);
INSERT INTO "public"."brain_map_sentences" VALUES ('178388ce-d440-40ca-a2d5-cde18ee381fe', '5d2a22dc-a9ed-4bf9-896b-1bf530d035cf', 'Her article appeared in last month’s issue.', '그녀의 기사는 지난달 호에 실렸다.', '간행물의 호', 'last month’s issue', 2, 2);
INSERT INTO "public"."brain_map_sentences" VALUES ('2a5e58c5-4efd-4bdc-a2ab-348b60cba4fa', '5d2a22dc-a9ed-4bf9-896b-1bf530d035cf', 'The government issued a warning about the storm.', '정부는 폭풍에 대한 경보를 발령했다.', '공식적으로 발표하다', 'issued a warning', 3, 3);

