INSERT INTO "public"."brain_maps" VALUES ('b7cc3605-7b42-4fcd-9829-9514451f9ac3', '97517ed1-2455-4f13-b1e1-02f5b79d1075', 'approved', 1, '어떤 상태가 끊기지 않고 계속 이어지도록 붙잡아 두다.', 'to keep something in the same condition, by continued effort', NULL, 'brain-map/2026-09-01', NULL, NULL, '2026-09-01 23:44:20.801+00', NULL, '2026-09-01 23:44:20.77432+00', '2026-09-01 23:44:20.77432+00');
