-- Data for Name: word_pair_questions; Type: TABLE DATA; Schema: public; Owner: -
--

INSERT INTO "public"."word_pair_questions" VALUES ('2b8ad029-b46f-4607-b013-1f99769462fb', '80591486-e21d-4163-92d4-ea16497e2dfa', 'The hospital must ___ strict hygiene standards at all times.', 'maintain', '병원이 위생 "기준"을 관리하고 지켜내는 상황이라 maintain이 자연스럽다.', 0);
INSERT INTO "public"."word_pair_questions" VALUES ('82046d0e-a4b5-4d00-94b2-4bd47df4e075', '80591486-e21d-4163-92d4-ea16497e2dfa', 'Please ___ the door open for a second.', 'keep', '잠깐 문을 그 상태로 두라는 일상적인 요청이므로 keep. 여기서 maintain은 지나치게 격식적이다.', 1);
INSERT INTO "public"."word_pair_questions" VALUES ('8294ad15-03a4-4642-bb6b-ce9db400ce38', '80591486-e21d-4163-92d4-ea16497e2dfa', 'Engineers ___ the bridge twice a year.', 'maintain', '정기적인 점검·보수를 뜻하므로 maintain.', 2);
INSERT INTO "public"."word_pair_questions" VALUES ('a637ba47-3d62-4cf7-aaf4-eee6371ba028', '54cb25bc-d0ea-47f1-8453-a59f3825e386', 'Too much caffeine can ___ your sleep.', 'affect', 'can 뒤에는 동사가 와야 하므로 affect.', 0);
INSERT INTO "public"."word_pair_questions" VALUES ('d1e49610-5b00-4f31-9cdb-f94593733c75', '54cb25bc-d0ea-47f1-8453-a59f3825e386', 'The medicine had no ___ on the pain.', 'effect', 'no 뒤에 오는 명사 자리이므로 effect.', 1);
INSERT INTO "public"."word_pair_questions" VALUES ('c9e44b0d-a0cc-4d73-b6c8-58103a29499d', '54cb25bc-d0ea-47f1-8453-a59f3825e386', 'Scientists studied the ___ of sunlight on plants.', 'effect', 'the ___ of 구조는 명사 자리이므로 effect.', 2);
INSERT INTO "public"."word_pair_questions" VALUES ('4d2efc81-b25e-4484-b28f-973ff8568c77', 'f3d9d3f7-83a6-481b-9dbb-e9e5df6dc6cc', 'Privacy is a major ___ in the age of social media.', 'issue', '사회적으로 논의되는 사안이므로 issue.', 0);
INSERT INTO "public"."word_pair_questions" VALUES ('1973c367-7d1e-4c4a-a9fc-9058cef9d945', 'f3d9d3f7-83a6-481b-9dbb-e9e5df6dc6cc', 'My laptop has a serious ___ with overheating.', 'problem', '고장이라는 부정적 상황이므로 problem이 자연스럽다.', 1);

--
-- Data for Name: word_pairs; Type: TABLE DATA; Schema: public; Owner: -
--

INSERT INTO "public"."word_pairs" VALUES ('80591486-e21d-4163-92d4-ea16497e2dfa', 'keep', 'maintain', 'keep은 그냥 계속 가지고 있거나 그 상태로 두는 것이고, maintain은 그 상태가 무너지지 않도록 의식적으로 노력하는 것이다. 그래서 maintain은 격식 있는 글이나 품질·질서·기계처럼 관리가 필요한 대상에 쓰인다.', '일상적인 "계속 ~하다"는 keep, 노력과 관리가 들어간 "유지하다"는 maintain.', 'approved', 1, NULL, NULL, '2026-09-01 23:44:20.868+00', '2026-09-01 23:44:20.77432+00');
INSERT INTO "public"."word_pairs" VALUES ('54cb25bc-d0ea-47f1-8453-a59f3825e386', 'affect', 'effect', 'affect는 거의 항상 동사로 "영향을 미치다", effect는 거의 항상 명사로 "영향, 결과"다. 발음이 비슷해서 헷갈리지만 문장에서의 자리가 완전히 다르다.', '앞에 the/an이 오면 effect(명사), 주어 뒤에 바로 오면 affect(동사)라고 생각하면 대부분 맞는다.', 'approved', 1, NULL, NULL, '2026-09-01 23:44:20.868+00', '2026-09-01 23:44:20.808379+00');
INSERT INTO "public"."word_pairs" VALUES ('f3d9d3f7-83a6-481b-9dbb-e9e5df6dc6cc', 'issue', 'problem', 'problem은 반드시 해결해야 하는 나쁜 상황이고, issue는 사람들이 논의하고 있는 사안이다. issue는 중립적일 수 있지만 problem은 거의 항상 부정적이다.', '고쳐야 할 고장·곤란은 problem, 토론하거나 다뤄야 할 사안은 issue.', 'approved', 1, NULL, NULL, '2026-09-01 23:44:20.868+00', '2026-09-01 23:44:20.82847+00');

